01M1GEP2E5DYT5VDPYVVTP548F	default_merchant	inventory	product	{"joins": [{"on": "pv.product_id = product.id", "type": "LEFT", "alias": "pv", "table": "product_variant"}, {"on": "pvii.variant_id = pv.id", "type": "LEFT", "alias": "pvii", "table": "product_variant_inventory_item"}, {"on": "il.inventory_item_id = pvii.inventory_item_id", "type": "LEFT", "alias": "il", "table": "inventory_level"}], "location": {"table": "il", "column": "location_id"}, "product_slug": {"table": "product", "column": "handle"}, "stock_quantity": {"table": "il", "column": "stocked_quantity"}}	t	\N	2026-09-02 07:00:11.333+00	2026-09-02 07:00:11.333+00	\N
01M1GENT0YRYRX0X53Z5VXZH0B	default_merchant	reviews	product_review	{"body": {"table": "product_review", "column": "content"}, "date": {"table": "product_review", "column": "created_at"}, "joins": [{"on": "p.id = product_review.product_id", "type": "LEFT", "alias": "p", "table": "product"}], "title": {"table": "product_review", "column": "title"}, "rating": {"table": "product_review", "column": "rating"}, "reviewer": {"table": "product_review", "column": "customer_name"}, "product_slug": {"table": "p", "column": "handle"}}	t	\N	2026-09-02 07:00:02.718+00	2026-09-02 07:00:02.718+00	\N
01M1GEN502Z06NHEN8FHH3C151	default_merchant	catalog	product	{"custom_sql": "SELECT p.title AS name, p.handle AS slug, p.subtitle AS brand, MIN(pr.amount) AS price, cat.name AS category, MIN(pr.currency_code) AS currency, p.description AS description FROM product p LEFT JOIN product_variant pv ON pv.product_id = p.id LEFT JOIN product_variant_price_set pvps ON pvps.variant_id = pv.id LEFT JOIN price pr ON pr.price_set_id = pvps.price_set_id AND pr.currency_code = 'inr' LEFT JOIN product_category_product pcp ON pcp.product_id = p.id LEFT JOIN product_category cat ON cat.id = pcp.product_category_id GROUP BY p.id, p.title, p.handle, p.subtitle, cat.name, p.description ORDER BY p.title"}	t	\N	2026-09-02 06:59:41.186+00	2026-09-02 07:00:23.152+00	\N
